// The only data the poll gets back: statuses and IDs for one write. It builds a
// new object, so no token, key or response body leaves this workflow.
const a = $('When called by the poll').first().json;
const tok = $('Installation token').first().json;
const back = $input.first().json || {};
const WRITE = {
  create_comment: 'Create comment', edit_comment: 'Edit comment', set_status: 'Set status',
  ensure_label: 'Create label', remove_label: 'Remove label', add_label: 'Add label',
};
// Rule 1: a label write counts only for these names.
const LABELS = ['triage:blocked', 'triage:deep-review', 'triage:review', 'triage:low-risk', 'triage:human', 'merge', 'merge-watched'];
const out = {
  run_id: a.run_id, repo: a.repo, pr: a.pr, head_sha: a.head_sha, index: a.index, type: a.type, name: a.name || null,
  token_status: tok.statusCode, write_status: null, readback_status: null, ok: false, comment_id: null, app_login: null,
};
if (!(tok.statusCode === 201 && WRITE[a.type])) return [{ json: out }];
if (/label$/.test(a.type) && !LABELS.includes(a.name)) return [{ json: out }];
const w = $(WRITE[a.type]).first().json || {};
const wb = w.body || {};
const b = back.body;
out.write_status = w.statusCode;
out.readback_status = back.statusCode;
const fromApp = (x) => !!(x && x.performed_via_github_app && String(x.performed_via_github_app.id) === String(a.app_id));
const names = Array.isArray(b) ? b.map((l) => l && l.name) : [];
if (a.type === 'create_comment' || a.type === 'edit_comment') {
  const wrote = a.type === 'create_comment' ? w.statusCode === 201 : w.statusCode === 200;
  out.ok = wrote && back.statusCode === 200 && !!b && b.body === a.body && fromApp(b)
    && (a.type === 'create_comment' || b.id === Number(a.comment_id));
  if (out.ok) {
    out.comment_id = b.id;
    out.app_login = b.user && b.user.login;
  }
} else if (a.type === 'set_status') {
  const s = Array.isArray(b) ? b.find((x) => x && x.context === 'pr-triage/verdict') : null;
  out.ok = w.statusCode === 201 && back.statusCode === 200 && !!s && s.state === a.state && s.description === a.description;
  if (out.ok && wb.creator) out.app_login = wb.creator.login;
} else if (a.type === 'ensure_label') {
  out.ok = (w.statusCode === 201 || w.statusCode === 422) && back.statusCode === 200 && !!b && b.name === a.name;
} else if (a.type === 'add_label') {
  out.ok = w.statusCode === 200 && back.statusCode === 200 && names.includes(a.name);
} else if (a.type === 'remove_label') {
  out.ok = (w.statusCode === 200 || w.statusCode === 404) && back.statusCode === 200 && Array.isArray(b) && !names.includes(a.name);
}
return [{ json: out }];
